fn frame(t: i32) {
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut r: i32 = 0;
        while r < 12 {
            host::display::state_set(8 + r, 0);
            r = r + 1;
        }
        host::display::state_set(9, 4);
        host::display::state_set(10, 8);
        host::display::state_set(11, 14);
        host::display::state_set(15, 7168);
        host::display::state_set(2, 4441);
        host::display::state_set(4, 0);
    }
    let mut cur = [0; 12];
    let mut r: i32 = 0;
    while r < 12 {
        cur[r] = host::display::state_get(8 + r);
        r = r + 1;
    }
    let down: i32 = host::display::pointer_down();
    if down == 1 && host::display::state_get(3) == 0 {
        let mut seed: i32 = host::display::state_get(2);
        r = 0;
        while r < 12 {
            seed = seed * 1103515245 + 12345;
            cur[r] = (seed >> 8) & 65535;
            host::display::state_set(8 + r, cur[r]);
            r = r + 1;
        }
        host::display::state_set(2, seed);
        host::display::state_set(4, 0);
    }
    host::display::state_set(3, down);
    if t % 8 == 0 {
        let mut nxt = [0; 12];
        r = 0;
        while r < 12 {
            let mut newrow: i32 = 0;
            let mut c: i32 = 0;
            while c < 16 {
                let mut n: i32 = 0;
                let mut dr: i32 = 0;
                while dr < 3 {
                    let mut dc: i32 = 0;
                    while dc < 3 {
                        if dr != 1 || dc != 1 {
                            let rr: i32 = (r + dr + 11) % 12;
                            let cc: i32 = (c + dc + 15) % 16;
                            n = n + ((cur[rr] >> cc) & 1);
                        }
                        dc = dc + 1;
                    }
                    dr = dr + 1;
                }
                let alive: i32 = (cur[r] >> c) & 1;
                if n == 3 || (alive == 1 && n == 2) {
                    newrow = newrow | (1 << c);
                }
                c = c + 1;
            }
            nxt[r] = newrow;
            r = r + 1;
        }
        r = 0;
        while r < 12 {
            cur[r] = nxt[r];
            host::display::state_set(8 + r, cur[r]);
            r = r + 1;
        }
        host::display::state_set(4, host::display::state_get(4) + 1);
    }
    host::display::clear(0x0a0a0a);
    r = 0;
    while r < 12 {
        let mut c: i32 = 0;
        while c < 16 {
            let col: i32 = if ((cur[r] >> c) & 1) == 1 { 0xd0ffd0 } else { 0x161816 };
            host::display::fill_rect(64 + c * 24, 100 + r * 24, 22, 22, col);
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::draw_string(64, 40, "GEN", 0x707070, 2);
    host::display::draw_number(130, 40, host::display::state_get(4), 0xffffff, 2);
    host::display::draw_string(64, 70, "TAP = RESEED", 0x505050, 1);
    host::display::present();
}
